      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "BINA, a pentamethyltetrahydronaphthalene-containing carboxylic acid, showed good in vivo brain penetration with a brain/plasma ratio of 0.75 at 2 h, supporting meaningful CNS access for this lipophilic acid family.",
      "evidence_role": "supportive"
    }
  ],
